import { execFileSync } from "child_process";
import * as fs from "fs";
import * as path from "path";

/**
 * Subjects generated by git itself for merge commits (see `git help merge`, `fmt-merge-msg`), which are
 * not recognized as such by the Commit's `isMergeCommit`, e.g. `Merge branch 'feature'` (without "into").
 */
const GIT_MERGE_SUBJECT = /^Merge (branch(es)?|remote-tracking branch(es)?|commit|tag|pull request #\d+)\b/;

/**
 * Checks whether the first line of the message is a merge subject as generated by git.
 * @param message The (full) commit message
 */
export function isGitMergeMessage(message: string): boolean {
  return GIT_MERGE_SUBJECT.test(message.split(/\r?\n/)[0].trim());
}

/**
 * Checks whether a merge is in progress (`MERGE_HEAD` exists), i.e. the commit being made is a merge commit.
 * @param cwd Directory inside the repository (defaults to the current working directory)
 */
export function isMergeInProgress(cwd?: string): boolean {
  try {
    const gitPath = execFileSync("git", ["rev-parse", "--git-path", "MERGE_HEAD"], {
      cwd,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    }).trim();
    return gitPath !== "" && fs.existsSync(path.resolve(cwd ?? ".", gitPath));
  } catch {
    return false;
  }
}
